[5566]={["id"]=5566,["name"]="La fleur fanée",["region"]="Guilde des voleurs — Trépas des Cognées / Thieves Guild - Quêtes secondairess",["site"]="Le débarcadère d’Abah",["regionName"]="Trépas des Cognées",["records"]={{["id"]=55660001,["order"]=1,["objective"]="Parlez à Velsa dans son jardin",["objectives"]={"Parlez à Velsa dans son jardin"},["steps"]={"Je dois rejoindre Velsa dans son jardin."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 1",["action"]="talk",["target"]="Velsa",["kind"]="person",["question"]="Savez-vous où je pourrais trouver Velsa ?"},{["id"]=55660002,["order"]=2,["objective"]="Lisez la lettre",["objectives"]={"Lisez la lettre"},["steps"]={"Au marché, une missive a été glissée dans les affaires de Velsa. Elle pense que c'est en lien avec sa famille ou qu'il s'agit un piège. Il me faut lire la lettre avant de poursuivre."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 2",["action"]="locate",["target"]="la lettre",["kind"]="object",["question"]="Savez-vous où se trouve la lettre ?"},{["id"]=55660003,["order"]=3,["objective"]="Trouvez le nordique à moitié nu",["objectives"]={"Trouvez le Nordique à moitié nu","Trouvez le nordique à moitié nu"},["steps"]={"Velsa ne se souvient de rien, sauf d'avoir été bousculée par un nordique à moitié nu. Elle pense qu'il se trouve au campement des marchands, hors de la ville. Je dois l'interroger au sujet de la lettre."},["hint"]="Près du camp marchand par l’oratoire du débarcadère d'Abah au Trépas des Cognées.",["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 3",["action"]="locate",["target"]="le nordique à moitié nu",["kind"]="object",["question"]="Savez-vous où se trouve le nordique à moitié nu ?"},{["id"]=55660004,["order"]=4,["objective"]="Rendez-vous à Rawl'kha à la marche de la Camarde",["objectives"]={"Rendez-vous à Rawl'kha à la marche de la Camarde"},["steps"]={"Le Nordique à moitié nu dit qu'une femme khajiit l'a payé pour qu'il dépose la lettre à Velsa à Rawl'kha. Il me faut partir à la marche de la Camarde en quête de cette mystérieuse Khajiit."},["hint"]="Par oratoire.",["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 4",["action"]="locate",["target"]="Rawl'kha à la marche de la Camarde",["kind"]="place",["question"]="Où se trouve Rawl'kha à la marche de la Camarde ?"},{["id"]=55660005,["order"]=5,["objective"]="Allez à Abondance, à Bangkoraï",["objectives"]={"Allez à Abondance, à Bangkoraï"},["steps"]={"Le Nordique à moitié nu dit qu'une femme khajiit l'a payé pour qu'il dépose la lettre à Velsa à Abondance. Il me faut partir à Bangkoraï en quête de cette mystérieuse Khajiit."},["hint"]="Par oratoire.",["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 5",["action"]="locate",["target"]="Abondance, à Bangkoraï",["kind"]="place",["question"]="Où se trouve Abondance, à Bangkoraï ?"},{["id"]=55660006,["order"]=6,["objective"]="Rendez-vous à Faillaise, à la Brèche",["objectives"]={"Rendez-vous à Faillaise, à la Brèche"},["steps"]={"Le Nordique à moitié nu dit qu'une femme khajiit l'a payé pour qu'il dépose la lettre à Velsa à Faillaise. Je dois chercher cette mystérieuse Khajiit à la Brèche."},["hint"]="Par oratoire.",["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 6",["action"]="locate",["target"]="Faillaise, à la Brèche",["kind"]="place",["question"]="Où se trouve Faillaise, à la Brèche ?"},{["id"]=55660007,["order"]=7,["objective"]="Trouvez la Khajiit",["objectives"]={"Trouvez la Khajiit"},["steps"]={"Je devrais demander à l'auberge si quelqu'un a des informations au sujet de ce mystérieux Khajiit."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 7",["action"]="locate",["target"]="la Khajiit",["kind"]="person",["question"]="Savez-vous où je pourrais trouver la Khajiit ?",["nativeOnly"]=true},{["id"]=55660008,["order"]=8,["objective"]="Parlez à Narahni",["objectives"]={"Parlez à Narahni"},["steps"]={"Je suis dans les appartements des serviteurs. Je dois interroger Narahni pour savoir si c'est elle qui a envoyé la lettre à Velsa."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 8",["action"]="talk",["target"]="Narahni",["kind"]="person",["question"]="Savez-vous où je pourrais trouver Narahni ?",["nativeOnly"]=true},{["id"]=55660009,["order"]=9,["objective"]="Retrouvez Narahni au débarcadère d'Abah",["objectives"]={"Retrouvez Narahni au débarcadère d'Abah"},["steps"]={"Narahni a envoyé la lettre à Velsa. Je l'ai convaincue de rencontrer Velsa en personne au débarcadère d'Abah. J'ai rendez-vous avec elle sur place."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 9",["action"]="locate",["target"]="Narahni au débarcadère d'Abah",["kind"]="object",["question"]="Savez-vous où se trouve Narahni au débarcadère d'Abah ?",["nativeOnly"]=true},{["id"]=55660010,["order"]=10,["objective"]="Parlez à Narahni",["objectives"]={"Parlez à Narahni"},["steps"]={"Je dois m'entretenir avec Narahni avant de l'escorter jusqu'à Velsa."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 10",["action"]="talk",["target"]="Narahni",["kind"]="person",["question"]="Savez-vous où je pourrais trouver Narahni ?"},{["id"]=55660011,["order"]=11,["objective"]="Réunissez Velsa et Narahni",["objectives"]={"Réunissez Velsa et Narahni"},["steps"]={"Narahni est prête, je vais la faire traverser l'entrepôt et le passage secret menant au jardin privé de Velsa, pour que les anciennes amies soient réunies