[5581]={["id"]=5581,["name"]="Ce qui était perdu",["region"]="Guilde des voleurs — Trépas des Cognées / Thieves Guild - Quêtes secondairess",["site"]="Le débarcadère d’Abah",["regionName"]="Trépas des Cognées",["records"]={{["id"]=55810001,["order"]=1,["objective"]="Parlez à Narahni",["objectives"]={"Parlez à Narahni"},["steps"]={"Je dois rejoindre Narahni pour entendre sa requête."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 1",["action"]="talk",["target"]="Narahni",["kind"]="person",["question"]="Savez-vous où je pourrais trouver Narahni ?"},{["id"]=55810002,["order"]=2,["objective"]="Examinez la lettre de Faradan",["objectives"]={"Examinez la lettre de Faradan"},["steps"]={"Il me faut examiner la lettre de Faradan adressée à Narahni. Elle pourrait m'éclairer sur la situation difficile de son fils Tashmin."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 2",["action"]="locate",["target"]="la lettre de Faradan",["kind"]="object",["question"]="Savez-vous où se trouve la lettre de Faradan ?"},{["id"]=55810003,["order"]=3,["objective"]="Allez à Gardeciel, à Auridia",["objectives"]={"Allez à Gardeciel, à Auridia"},["steps"]={"La lettre de Faradan explique que des chasseurs de primes à Gardeciel ont capturé le fils de Narahni, Tashmin. Il a été vu en compagnie d'une jeune Brétonne juste avant d'être capturé. Je devrais me rendre à Auridia pour tenter de retrouver leur piste."},["hint"]="Sur la côte est de l'île.",["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 3",["action"]="locate",["target"]="Gardeciel, à Auridia",["kind"]="place",["question"]="Où se trouve Gardeciel, à Auridia ?"},{["id"]=55810004,["order"]=4,["objective"]="Trouvez l'amie de Tashmin",["objectives"]={"Trouvez l'amie de Tashmin"},["steps"]={"La lettre de Faradan évoque une jeune Brétonne aperçue en compagnie de Tashmin juste avant sa capture. Je dois tenter de la retrouver."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 4",["action"]="locate",["target"]="l'amie de Tashmin",["kind"]="object",["question"]="Savez-vous où se trouve l'amie de Tashmin ?",["nativeOnly"]=true},{["id"]=55810005,["order"]=5,["objective"]="Obtenez la page du journal d'Erendette",["objectives"]={"Obtenez la page du journal d'Erendette"},["steps"]={"Je dois déchirer la page décrivant la dette d'Erendette dans le registre. Son trafiquant de skouma le garde dans un coffre verrouillé. Elle me révélera ensuite ce qu'elle sait au sujet de Tashmin."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 5",["action"]="locate",["target"]="la page du journal d'Erendette",["kind"]="object",["question"]="Savez-vous où se trouve la page du journal d'Erendette ?",["nativeOnly"]=true},{["id"]=55810006,["order"]=6,["objective"]="Donnez la page du registre à Erendette",["objectives"]={"Donnez la page du registre à Erendette"},["steps"]={"J'ai récupéré la page de la dette qu'Erendette doit à son trafiquant de skouma. Je dois la lui apporter."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 6",["action"]="deliver",["target"]="Erendette",["item"]="la page du registre",["kind"]="person",["question"]="Savez-vous où je pourrais trouver Erendette ?",["nativeOnly"]=true},{["id"]=55810007,["order"]=7,["objective"]="Cherchez Tashmin non loin des quais",["objectives"]={"Cherchez Tashmin non loin des quais"},["steps"]={"Selon l'amie de Tashmin, les deux Elfes noirs qui l'ont capturé l'ont ligoté puis abandonné non loin des quais pour arrêter d'autres malheureux et les réduire en esclavage. Il me faut arpenter les quais et ses environs, en espérant y trouver Tash."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 7",["action"]="locate",["target"]="Tashmin non loin des quais",["kind"]="object",["question"]="Savez-vous où se trouve Tashmin non loin des quais ?",["nativeOnly"]=true},{["id"]=55810008,["order"]=8,["objective"]="Retrouvez Tashmin en ville",["objectives"]={"Retrouvez Tashmin en ville"},["steps"]={"Tashmin s'est enfui. Je le retrouverai sur les lieux dont il m'a parlé juste avant de me quitter sur les quais."},["hint"]=nil,["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 8",["action"]="locate",["target"]="Tashmin en ville",["kind"]="object",["question"]="Savez-vous où se trouve Tashmin en ville ?",["nativeOnly"]=true},{["id"]=55810009,["order"]=9,["objective"]="Parlez à Tashmin",["objectives"]={"Parlez à Tashmin"},["steps"]={"Je dois parler à Tashmin et m'assurer qu'il est bien prêt à retrouver sa mère."},["hint"]="Dans le passage d'entrée de la citerne dans la tanière.",["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 9",["action"]="talk",["target"]="Tashmin",["kind"]="person",["question"]="Savez-vous où je pourrais trouver Tashmin ?"},{["id"]=55810010,["order"]=10,["objective"]="Réunissez Tashmin et Narahni",["objectives"]={"Réunissez Tashmin et Narahni"},["steps"]={"Tashmin est prêt à se réunir avec sa mère. À présent, je dois l'escorter jusqu'à elle."},["hint"]="Accompagnez-le jusqu’à l’emplacement de Velsa, dans la partie sud du tombeau.",["site"]="Le débarcadère d’Abah",["source"]="Immersive Quests FR — référence reprise du fichier local, bloc 10",["action"]="locate",["target"]="Tashmin et Narahni",["kind"]="object",["question"]="Savez-vous où se trouve Tashmin et Narahni ?"}},["cast"]={"Erendette","Narahni","Tashmin","Message from Velsa"},["repeatable"]=false},
